#include <iostream>

class BankAccount {
public:
    bool deposit(long long cents) {
        if (cents <= 0) return false;
        cents_ += cents;
        return true;
    }
    bool withdraw(long long cents) {
        if (cents <= 0 || cents > cents_) return false;
        cents_ -= cents;
        return true;
    }
    long long balance() const { return cents_; }
private:
    long long cents_ = 0;
};

