#include <algorithm>
#include <cstddef>
#include <iostream>
#include <numeric>
#include <vector>

class GradeBook {
public:
    bool add(int score) {
        if (score < 0 || score > 100) return false;
        scores_.push_back(score);
        return true;
    }
    double mean() const {
        if (scores_.empty()) return 0.0;
        return std::accumulate(scores_.begin(), scores_.end(), 0.0) / scores_.size();
    }
    int max() const {
        if (scores_.empty()) return -1;
        return *std::max_element(scores_.begin(), scores_.end());
    }
    std::size_t size() const { return scores_.size(); }
private:
    std::vector<int> scores_;
};

int main() {
    GradeBook g;
    g.add(80); g.add(90); g.add(70);
    std::cout << g.mean() << ' ' << g.max() << '\n';  // 80 90
}
```

