#include <cstdint>
#include <iostream>

class IntervalTimer {
public:
    explicit IntervalTimer(std::uint32_t interval_ms) : interval_{interval_ms} {}
    bool ready(std::uint32_t now) {
        if (static_cast<std::uint32_t>(now - last_) >= interval_) {
            last_ = now;
            return true;
        }
        return false;
    }
private:
    std::uint32_t interval_;
    std::uint32_t last_ = 0;
};

int main() {
    IntervalTimer t{500};
    std::cout << t.ready(100) << t.ready(500) << t.ready(900) << t.ready(1000) << '\n';  // 0101
}
```

