On the real board, upload this and open **Tools → Serial Plotter** (Arduino IDE 2 on macOS; close the Serial Monitor first, only one can hold `/dev/cu.usbmodem…`):

```arduino
const int TRIG = 9, ECHO = 10;
float buf[5]; int idx = 0; float avg = 0;

float readCm() {
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);
  return us == 0 ? 400.0 : us / 58.3;
}

float median5(const float* v) {
  float s[5];
  for (int i = 0; i < 5; i++) s[i] = v[i];
  for (int i = 1; i < 5; i++)                     // insertion sort, 5 items
    for (int j = i; j > 0 && s[j] < s[j - 1]; j--) { float t = s[j]; s[j] = s[j - 1]; s[j - 1] = t; }
  return s[2];
}

void setup() { Serial.begin(115200); pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

void loop() {
  float raw = readCm();
  buf[idx] = raw; idx = (idx + 1) % 5;
  float med = median5(buf);
  avg += 0.3 * (med - avg);
  Serial.print("raw:"); Serial.print(raw);
  Serial.print(",median:"); Serial.print(med);
  Serial.print(",smooth:"); Serial.println(avg);
  delay(60);
