from collections import deque
from dataclasses import dataclass
import math

@dataclass
class Reading:
    ms: int
    raw: float
    filtered: float

def parse_line(line):
    line = line.strip()
    if not line or line.startswith("#") or line.startswith("ms,"):
        return None
    parts = line.split(",")
    if len(parts) != 3:
        return None
    try:
        return Reading(int(parts[0]), float(parts[1]), float(parts[2]))
    except ValueError:
        return None

class Rolling:
    def __init__(self, n=30):
        self.values = deque(maxlen=n)

    def add(self, v):
        self.values.append(v)

    def stats(self):
        if not self.values:
            return None
        m = sum(self.values) / len(self.values)
        var = sum((v - m) ** 2 for v in self.values) / len(self.values)
        return {"mean": m, "min": min(self.values), "max": max(self.values), "std": math.sqrt(var)}

